// Vibrant color palette function
vec3 palette(float t) {
    vec3 a = vec3(-0.202, 0.488, 0.398);
    vec3 b = vec3(0.908, 0.458, -0.702);
    vec3 c = vec3(0.068, -0.592, 1.000);
    vec3 d = vec3(0.000, 0.333, 0.667);
    return a + b * cos(6.28318 * (c * t + d));
}

// Fetch audio data from iChannel0
float getAudioSample(float y) {
    return texture(iChannel0, vec2(y * 0.5 + 0.5, 0.25)).r; // Sample audio texture
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    // Perspective distortion for dynamic depth
    uv /= 1.0 - uv.y * 1.55;

    vec2 uv0 = uv;
    vec3 finalColor = vec3(0.0);

    // Audio data influencing transformations
    float audio = getAudioSample(uv.y);
    float timeFactor = iTime + audio * 2.0; // Audio-reactive time factor

    uv.x += 2.0 * cos(timeFactor * 0.2);
    uv.y += 2.0 * sin(timeFactor * 0.2);

    for (float i = 0.0; i < 7.0; i++) {
        uv.x += 2.0 * cos(timeFactor * 0.2 + i * audio);
        uv.y += 2.0 * sin(timeFactor * 0.2 + i * audio);
        uv = fract(uv * (2.5 + audio * 1.0)) - 0.5;

        // Distance modulation with glow
        float d = length(uv) * exp(-length(uv0));
        vec3 col = palette(length(uv0) + i * 0.4 + timeFactor * 0.4);

        d = sin(d * 8.0 + timeFactor) / 8.0;
        d = abs(d);
        d = 0.05 / d;
        d = pow(0.15 / d, 1.9);

        finalColor += col * d * (0.8 + 0.5 * audio); // Additive glow with audio influence
    }

    // Enhance glow for a psychedelic effect
    finalColor = pow(finalColor, vec3(0.8)) + 1.1 * audio;

    fragColor = vec4(finalColor, 1.0);
}
